/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dlaqsy = require( './../lib/dlaqsy.js' );


// FIXTURES //

var ROW_MAJOR_UPPER = require( './fixtures/row_major_upper.json' );
var ROW_MAJOR_LOWER = require( './fixtures/row_major_lower.json' );
var COLUMN_MAJOR_UPPER = require( './fixtures/column_major_upper.json' );
var COLUMN_MAJOR_LOWER = require( './fixtures/column_major_lower.json' );
var AMAX_LARGE_UPPER = require( './fixtures/amax_large_upper.json' );
var AMAX_LARGE_LOWER = require( './fixtures/amax_large_lower.json' );
var AMAX_SMALL = require( './fixtures/amax_small.json' );
var NO_EQUILIBRATION = require( './fixtures/no_equilibration.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlaqsy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 8', function test( t ) {
	t.strictEqual( dlaqsy.length, 8, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var A;
	var S;
	var i;

	A = new Float64Array( 9 );
	S = new Float64Array( 3 );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlaqsy( value, 'upper', 3, A, 3, S, 0.05, 9.0 );
		};
	}
});

