tape( 'the function equilibrates a symmetric matrix (row-major, upper)', function test( t ) {
	var expected;
	var equed;
	var data;
	var A;
	var S;

	data = ROW_MAJOR_UPPER;

	A = new Float64Array( data.A );
	S = new Float64Array( data.S );

	equed = dlaqsy( data.order, data.uplo, data.N, A, data.LDA, S, data.scond, data.amax );
	expected = new Float64Array( data.A_out );

	t.strictEqual( equed, data.equed, 'returns expected value' );
	t.deepEqual( A, expected, 'returns expected value' );
	t.end();
});

