tape( 'the function does not equilibrate a symmetric matrix if equilibration is not needed', function test( t ) {
	var expected;
	var equed;
	var data;
	var A;
	var S;

	data = NO_EQUILIBRATION;

	A = new Float64Array( data.A );
	S = new Float64Array( data.S );

	equed = dlaqsy( data.order, data.uplo, data.N, A, data.LDA, S, data.scond, data.amax );
	expected = new Float64Array( data.A_out );

	t.strictEqual( equed, 'N', 'returns expected value' );
	t.deepEqual( A, expected, 'returns expected value' );
	t.end();
});

tape( 'the function returns `N` and leaves the input matrix unchanged if `N` is equal to zero', function test( t ) {
	var expected;
	var equed;
	var A;
	var S;

	A = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	S = new Float64Array( [ 0.1, 10.0 ] );
	expected = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );

	equed = dlaqsy( 'row-major', 'upper', 0, A, 2, S, 0.01, 4.0 );
	t.strictEqual( equed, 'N', 'returns expected value' );
	t.deepEqual( A, expected, 'returns expected value' );

	equed = dlaqsy( 'column-major', 'lower', 0, A, 2, S, 0.01, 4.0 );
	t.strictEqual( equed, 'N', 'returns expected value' );
	t.deepEqual( A, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports specifying a leading dimension which is greater than the number of columns (row-major)', function test( t ) {
	var expected;
	var equed;
	var A;
	var S;

	A = new Float64Array( [ 1.0, 2.0, 9999.0, 2.0, 5.0, 9999.0 ] );
	S = new Float64Array( [ 0.25, 4.0 ] );
	expected = new Float64Array( [ 0.0625, 2.0, 9999.0, 2.0, 80.0, 9999.0 ] );

	equed = dlaqsy( 'row-major', 'upper', 2, A, 3, S, 0.0625, 5.0 );
	t.strictEqual( equed, 'Y', 'returns expected value' );
	t.deepEqual( A, expected, 'returns expected value' );
	t.end();
});

